package com.mannvaasam.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { @Value("${app.jwt-secret}") String secret; SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String create(Long id,String email,String role){return Jwts.builder().subject(email).claim("id",id).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key()).compact();} public Claims parse(String t){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(t).getPayload();} }